def solution(s):
    """
    Count the number of unique characters in the string, where a unique character appears exactly once.

    Args:
    s (str): The input string to analyze.

    Returns:
    int: The number of unique characters in the string.
    """
    # Initialize a dictionary to keep track of character counts
    char_counts = {}

    # Iterate through each character in the string
    for char in s:
        # Increment the count for the current character
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    # Count the number of characters with exactly one occurrence
    unique_count = 0
    for count in char_counts.values():
        if count == 1:
            unique_count += 1

    return unique_count

