import unittest

class TestCountUniqueCharacters(unittest.TestCase):
    def test_simple_case(self):
        """Test with a simple string containing some unique characters."""
        self.assertEqual(solution("hello"), 3)

    def test_no_unique_chars(self):
        """Test with a string that has no unique characters (all duplicates)."""
        self.assertEqual(solution("aabbcc"), 0)

    def test_all_unique_chars(self):
        """Test with a string where all characters are unique."""
        self.assertEqual(solution("abc"), 3)

    def test_empty_string(self):
        """Test with an empty string (should return 0)."""
        self.assertEqual(solution(""), 0)

    def test_single_char(self):
        """Test with a single character string (should return 1)."""
        self.assertEqual(solution("z"), 1)

    def test_case_sensitivity(self):
        """Test case sensitivity (uppercase and lowercase should be different)."""
        self.assertEqual(solution("AaBbCc"), 6)

    def test_with_spaces(self):
        """Test with spaces as part of the string."""
        self.assertEqual(solution("a a b b c"), 1)  # only 'c' is unique

    def test_with_punctuation(self):
        """Test with punctuation characters."""
        self.assertEqual(solution("hello, world!"), 4)  # ',', 'w', 'r', 'd', '!' are unique

    def test_mixed_characters(self):
        """Test with a mix of letters, numbers, and special characters."""
        self.assertEqual(solution("a1@b2#c3$"), 6)  # only '1', '2', '3' are duplicates

    def test_repeated_non_consecutive(self):
        """Test with characters that repeat but not consecutively."""
        self.assertEqual(solution("abacaba"), 1)  # only 'c' is unique

    def test_max_length_string(self):
        """Test with maximum length string (1000 chars) all unique."""
        s = ''.join(chr(i) for i in range(32, 1032))  # 1000 unique ASCII characters
        self.assertEqual(solution(s), 1000)

    def test_max_length_single_char(self):
        """Test with maximum length string of same character."""
        s = 'a' * 1000
        self.assertEqual(solution(s), 0)

    def test_unicode_characters(self):
        """Test with Unicode characters beyond ASCII range."""
        self.assertEqual(solution("😊😊❤️"), 1)  # only '❤️' is unique (note: ❤️ is actually two chars)
        self.assertEqual(solution("αβγα"), 2)    # Greek letters

    def test_whitespace_variations(self):
        """Test with various whitespace characters."""
        self.assertEqual(solution(" \t\n\r\x0b\x0c"), 6)  # all are unique

    def test_numeric_string(self):
        """Test with string containing only numbers."""
        self.assertEqual(solution("1122334455"), 0)
        self.assertEqual(solution("12345"), 5)

if __name__ == '__main__':
    unittest.main()

