    A character is considered unique if it appears exactly once in the string.

    Args:
        s (str): The input string to analyze.

    Returns:
        int: The count of unique characters in the string.
    """
    # Initialize a dictionary to store the count of each character
    char_count = {}

    # Count the occurrences of each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count how many characters appear exactly once
    unique_count = 0
    for count in char_count.values():
        if count == 1:
            unique_count += 1

    return unique_count

