def solution(s):
    """
    Finds the most frequent character in the string. If multiple characters have the same highest frequency,
    returns the one that appears first in the string.

    Args:
    s (str): The input string.

    Returns:
    str: The most frequent character.
    """
    if not s:
        return ''  # handle empty string case, though constraints say 1 <= s.length

    frequency = {}
    max_char = s[0]
    max_count = 1  # Initialize to 1 since we're starting with first character

    # First pass to count frequencies
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Second pass to find the first character with max frequency
    for char in s:
        if frequency[char] > max_count:
            max_count = frequency[char]
            max_char = char

    return max_char

