def solution(num):
    """
    Classifies an integer input as positive, negative, or zero.

    Args:
        num: An integer to be classified

    Returns:
        A string: "positive", "negative", or "zero"

    Raises:
        ValueError: If input is not an integer
    """
    if isinstance(num, bool):
        raise ValueError("Input must be an integer")
    if not isinstance(num, int):
        raise ValueError("Input must be an integer")

    if num > 0:
        return "positive"
    elif num < 0:
        return "negative"
    else:
        return "zero"

