def solution(operations):
    """
    Implements a simple stack with push, pop, and top operations.

    Args:
        operations: A list of strings representing stack operations.

    Returns:
        A list of integers representing the results of pop and top operations.
    """
    stack = []
    result = []

    for op in operations:
        if op.startswith("push"):
            # Extract the number after "push "
            num = int(op.split()[1])
            stack.append(num)
        elif op == "pop":
            if stack:
                result.append(stack.pop())
            else:
                result.append(-1)
        elif op == "top":
            if stack:
                result.append(stack[-1])
            else:
                result.append(-1)

    return result

def solution(operations):
    """
    Implements a simple stack with push, pop, and top operations.
    Only returns results for pop and top operations, not for push operations.

    Args:
        operations: A list of strings representing stack operations.

    Returns:
        A list of integers representing the results of pop and top operations.
    """
    stack = []
    result = []

    for op in operations:
        if op.startswith("push"):
            # Extract the number after "push " and push to stack
            num = int(op.split()[1])
            stack.append(num)
        elif op == "pop":
            # Pop from stack or return -1 if empty
            if stack:
                result.append(stack.pop())
            else:
                result.append(-1)
        elif op == "top":
            # Peek at top of stack or return -1 if empty
            if stack:
                result.append(stack[-1])
            else:
                result.append(-1)

    return result

def solution(operations):
    """
    Implements a simple stack with push, pop, and top operations.

    Args:
        operations: A list of strings representing stack operations.

    Returns:
        A list of integers representing the results of pop and top operations.
    """
    stack = []
    result = []

    for op in operations:
        if op.startswith("push"):
            # Push operation - add to stack, no output
            num = int(op.split()[1])
            stack.append(num)
        elif op == "pop":
            # Pop operation - remove and return top element or -1 if empty
            if not stack:
                result.append(-1)
            else:
                result.append(stack.pop())
        elif op == "top":
            # Top operation - return top element without removing or -1 if empty
            if not stack:
                result.append(-1)
            else:
                result.append(stack[-1])

    return result

