def solution(s):
    """
    Reverses the input string if it is a valid string, otherwise returns an error message.

    Args:
    s: The input to be reversed. Expected to be a string.

    Returns:
    str: The reversed string if the input is a valid string, otherwise an error message.
    """
    if not isinstance(s, str):
        return "Error: Input must be a string."

    def reverse_string(s):
        if len(s) <= 1:
            return s
        return s[-1] + reverse_string(s[:-1])

    return reverse_string(s)

