def solution(nums, target):
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    # Find the pivot (smallest element)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    pivot = left

    # Reset search boundaries
    left, right = 0, len(nums) - 1

    # Determine which side to search
    if nums[pivot] <= target <= nums[right]:
        left = pivot
    else:
        right = pivot - 1

    # Regular binary search
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1
