def solution(arr, target):
    """
    Performs a recursive binary search on a sorted array to find the target value.

    Args:
        arr (list): A sorted list of integers.
        target (int): The value to search for in the array.

    Returns:
        int: The index of the target if found, otherwise -1.
    """
    def binary_search(left, right):
        # Base case: if the left index exceeds the right index, target not found
        if left > right:
            return -1
        # Calculate the middle index
        mid = (left + right) // 2
        # If the middle element is the target, return its index
        if arr[mid] == target:
            return mid
        # If the target is smaller than the middle element, search left half
        elif arr[mid] > target:
            return binary_search(left, mid - 1)
        # If the target is larger than the middle element, search right half
        else:
            return binary_search(mid + 1, right)

    # Initial call to binary search with the full range of the array
    return binary_search(0, len(arr) - 1)

