def solution(nums):
    """
    Calculate the length of the longest strictly increasing subsequence in the given array.

    Args:
    nums (List[int]): An array of integers.

    Returns:
    int: The length of the longest strictly increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize all dp values to 1, as each element is a subsequence of length 1

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

