def solution(m, n):
    # Create a 2D DP array initialized to 1. The first row and first column are all 1.
    dp = [[1 for _ in range(n)] for _ in range(m)]

    for i in range(1, m):
        for j in range(1, n):
            # The number of paths to (i,j) is the sum of paths from above and from the left.
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

