def solution(arr, target):
    """
    Searches for the target in the given list and returns the count of its occurrences
    along with the index of its first occurrence. If the target is not found, returns (-1, -1).

    Args:
    arr (List[int]): The list of integers to search.
    target (int): The integer to search for in the list.

    Returns:
    Tuple[int, int]: A tuple containing the count of occurrences and the first index.
                     Returns (-1, -1) if the target is not found.
    """
    count = 0
    first_index = -1

    for index, num in enumerate(arr):
        if num == target:
            if first_index == -1:
                first_index = index
            count += 1

    if count > 0:
        return (count, first_index)
    else:
        return (-1, -1)

