        """Test with empty array input."""
        self.assertEqual(solution([], 5), -1)

    def test_single_element_found(self):
        """Test with single element array where target exists."""
        self.assertEqual(solution([5], 5), 0)

    def test_single_element_not_found(self):
        """Test with single element array where target doesn't exist."""
        self.assertEqual(solution([3], 5), -1)

    def test_duplicate_elements_valid_rotation(self):
        """Test with valid rotated array containing duplicates."""
        self.assertEqual(solution([2,2,2,3,1,1,1], 3), 3)

