def solution(nums, target):
    """
    Searches for a target value in a rotated sorted array and returns its index if found.
    If the target is not found, returns -1. If the input array is invalid (not sorted or
    contains non-integer elements), returns "Invalid Input".

    Args:
        nums: List of integers (or potentially mixed types if invalid).
        target: Integer to search for in the array.

    Returns:
        int: Index of target if found, -1 if not found.
        str: "Invalid Input" if the input array is invalid.
    """
    # Check for non-integer elements in nums
    if not all(isinstance(num, int) for num in nums):
        return "Invalid Input"

    # Check if the array is a rotated version of a sorted array
    def is_rotated_sorted(arr):
        n = len(arr)
        if n == 0:
            return True
        rotated = False
        for i in range(1, n):
            if arr[i] < arr[i-1]:
                if rotated:
                    return False  # More than one rotation point
                rotated = True
        # Check if the last element is <= first element (for rotated arrays)
        if rotated and arr[-1] > arr[0]:
            return False
        return True

    if not is_rotated_sorted(nums):
        return "Invalid Input"

    # Binary search implementation for rotated sorted array
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid

        # Check if the left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target <= nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] <= target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

