    """
    Searches for a target value in a rotated sorted array and returns its index if found.
    If the target is not found, returns -1. If the input array is invalid (not sorted or
    contains non-integer elements), returns "Invalid Input".
    """
    # Check for non-integer elements in nums
    if not all(isinstance(num, int) for num in nums):
        return "Invalid Input"

    # Check if the array is a rotated version of a sorted array
    def is_rotated_sorted(arr):
        if len(arr) <= 1:
            return True
        pivot = 0
        for i in range(1, len(arr)):
            if arr[i] < arr[i-1]:
                pivot = i
                break
        # Check if both parts are sorted
        return (all(arr[i] <= arr[i+1] for i in range(pivot, len(arr)-1)) and
                (pivot == 0 or arr[-1] <= arr[0]))

    if not is_rotated_sorted(nums):
        return "Invalid Input"

    # Binary search implementation
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid

        # Determine which part is properly sorted
        if nums[left] <= nums[mid]:  # Left half is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right half is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

