class TestMedianOfTwoSortedArrays(unittest.TestCase):
    def test_basic_case_odd_length(self):
        """Test basic case with odd total length of merged array."""
        self.assertEqual(solution([1, 3], [2]), 2.0)

    def test_basic_case_even_length(self):
        """Test basic case with even total length of merged array."""
        self.assertEqual(solution([1, 2], [3, 4]), 2.5)

    def test_one_empty_array_odd_length(self):
        """Test case where one array is empty (odd length)."""
        self.assertEqual(solution([], [1, 2, 3]), 2.0)

    def test_one_empty_array_even_length(self):
        """Test case where one array is empty (even length)."""
        self.assertEqual(solution([], [1, 2, 3, 4]), 2.5)

    def test_both_empty_arrays(self):
        """Test case where both arrays are empty (should raise error)."""
        with self.assertRaises(ValueError):
            solution([], [])

    def test_identical_arrays_odd_length(self):
        """Test case with identical arrays (odd total length)."""
        self.assertEqual(solution([1, 2, 3], [1, 2, 3]), 2.0)

    def test_identical_arrays_even_length(self):
        """Test case with identical arrays (even total length)."""
        self.assertEqual(solution([1, 2], [1, 2]), 1.5)

    def test_non_overlapping_arrays(self):
        """Test case with non-overlapping arrays."""
        self.assertEqual(solution([1, 2], [3, 4, 5, 6]), 3.5)

    def test_completely_overlapping_arrays(self):
        """Test case where one array is completely contained within another."""
        self.assertEqual(solution([1, 2, 3, 4, 5], [2, 3, 4]), 3.0)

    def test_negative_numbers(self):
        """Test case with negative numbers in arrays."""
        self.assertEqual(solution([-5, -3, -1], [-4, -2, 0]), -2.5)

    def test_single_element_arrays(self):
        """Test case with single-element arrays."""
        self.assertEqual(solution([1], [2]), 1.5)

    def test_large_arrays(self):
        """Test case with large arrays (boundary of constraints)."""
        nums1 = list(range(1000))
        nums2 = list(range(1000, 2000))
        self.assertEqual(solution(nums1, nums2), 999.5)

    def test_duplicate_values(self):
        """Test case with duplicate values across arrays."""
        self.assertEqual(solution([1, 1, 1, 2, 2], [1, 2, 2, 3]), 2.0)

    def test_one_array_single_element(self):
        """Test case where one array has only one element."""
        self.assertEqual(solution([1, 2, 3, 4, 5, 6], [4]), 4.0)

    def test_extreme_value_difference(self):
        """Test case with extreme value differences between arrays."""
        self.assertEqual(solution([-1000000, 0, 1000000], [-500000, 500000]), 0.0)

