def solution(nums, target):
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            return True

        # Skip duplicates from left and right if they are the same as mid
        while left < mid and nums[left] == nums[mid]:
            left += 1
        while mid < right and nums[mid] == nums[right]:
            right -= 1

        if nums[left] <= nums[mid]:  # Left half is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right half is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return False

def solution(nums, target):
    """
    Search for a target in a rotated sorted array using a modified binary search.

    Args:
    nums: List[int] - A rotated sorted array of distinct integers.
    target: int - The integer to search for in the array.

    Returns:
    int - The index of the target if found, otherwise -1.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        # Check if the left half is sorted
        if nums[left] <= nums[mid]:
            # If target is within the sorted left half, search in the left half
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right half is sorted, check if target is within the right half
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

