    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid

        # Check if the left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Else the right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def solution(nums, target):
    def recursive_search(left, right):
        if left > right:
            return -1
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        # Check if the left half is sorted
        if nums[left] < nums[mid]:
            if nums[left] <= target < nums[mid]:
                return recursive_search(left, mid - 1)
            else:
                return recursive_search(mid + 1, right)
        elif nums[left] > nums[mid]:
            if nums[mid] < target <= nums[right]:
                return recursive_search(mid + 1, right)
            else:
                return recursive_search(left, mid - 1)
        else:
            # Handle duplicates: nums[left] == nums[mid], search both halves
            if nums[mid] != nums[right]:  # right side is different
                return recursive_search(mid + 1, right)
            else:
                # Both sides could have the target, search both
                result = recursive_search(left, mid - 1)
                if result != -1:
                    return result
                return recursive_search(mid + 1, right)
    return recursive_search(0, len(nums) - 1)

