def solution(transactions, initial_balances):
    # Create a copy of initial balances to avoid modifying the input
    balances = initial_balances.copy()
    errors = []

    # Sort transactions by timestamp to ensure chronological processing
    sorted_transactions = sorted(transactions, key=lambda x: x["timestamp"])

    for transaction in sorted_transactions:
        account_id = transaction["account_id"]
        amount = transaction["amount"]
        transaction_type = transaction["type"]

        # Ensure account exists in balances (though initial_balances should have all accounts)
        if account_id not in balances:
            balances[account_id] = 0

        if transaction_type == "deposit":
            # Deposits are always valid - simply add to balance
            balances[account_id] += amount
        elif transaction_type == "withdrawal":
            # Check if withdrawal amount exceeds balance
            if amount > balances[account_id]:
                errors.append(f"Withdrawal of {amount} exceeds balance for account {account_id}.")
            else:
                balances[account_id] -= amount
        else:
            # Handle unknown transaction types (though constraints say it's either deposit or withdrawal)
            errors.append(f"Unknown transaction type '{transaction_type}' for account {account_id}.")

    return (balances, errors)

