def solution(transactions, initial_balances):
    from datetime import datetime

    # Create a copy of initial balances to avoid modifying the input
    balances = initial_balances.copy()
    errors = []

    # Separate valid and invalid transactions
    valid_transactions = []
    invalid_transactions = []

    for transaction in transactions:
        try:
            # Validate timestamp format
            datetime.strptime(transaction["timestamp"], "%Y-%m-%d %H:%M:%S")
            valid_transactions.append(transaction)
        except ValueError:
            invalid_transactions.append(transaction)
            errors.append(f"Invalid timestamp format for transaction on account {transaction['account_id']}")

    # Sort only valid transactions by timestamp
    sorted_transactions = sorted(
        valid_transactions,
        key=lambda x: datetime.strptime(x["timestamp"], "%Y-%m-%d %H:%M:%S")
    )

    for transaction in sorted_transactions:
        account_id = transaction["account_id"]
        amount = transaction["amount"]
        transaction_type = transaction["type"]

        # Ensure account exists in balances
        balances.setdefault(account_id, 0)

        if transaction_type == "deposit":
            balances[account_id] += amount
        elif transaction_type == "withdrawal":
            if amount > balances[account_id]:
                errors.append(f"Withdrawal of {amount} exceeds balance for account {account_id}.")
            else:
                balances[account_id] -= amount
        else:
            errors.append(f"Unknown transaction type '{transaction_type}' for account {account_id}.")

    return (balances, errors)

