def solution(matrix, target):
    if not matrix or not matrix[0]:
        return False

    rows = len(matrix)
    cols = len(matrix[0])

    def search_recursive(lr, lc, hr, hc):
        if lr > hr or lc > hc:
            return False
        mid_row = (lr + hr) // 2
        mid_col = (lc + hc) // 2
        current = matrix[mid_row][mid_col]
        if current == target:
            return True
        elif current < target:
            # Search right submatrix and bottom submatrix
            return search_recursive(mid_row + 1, lc, hr, hc) or search_recursive(lr, mid_col + 1, hr, hc)
        else:
            # Search left submatrix and top submatrix
            return search_recursive(lr, lc, mid_row - 1, hc) or search_recursive(lr, lc, hr, mid_col - 1)

    return search_recursive(0, 0, rows - 1, cols - 1)

