from typing import List
import math

class NumberClassifier:
    @staticmethod
    def is_prime(n: int) -> bool:
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    @staticmethod
    def is_perfect_square(n: int) -> bool:
        """Check if a number is a perfect square."""
        if n < 0:
            return False
        root = math.isqrt(n)
        return root * root == n

    @classmethod
    def classify_numbers(cls, numbers: List[int]) -> List[str]:
        """Classify each number in the input list based on the given rules."""
        # Check if all elements are integers
        if not all(isinstance(num, int) for num in numbers):
            raise ValueError("Input must be a list of integers.")

        classifications = []
        for num in numbers:
            if num < 0:
                classifications.append("Negative")
            elif num == 0:
                classifications.append("Zero")
            elif cls.is_prime(num):
                classifications.append("Prime")
            elif cls.is_perfect_square(num):
                classifications.append("Perfect Square")
            elif num % 2 == 0:
                classifications.append("Even Positive")
            else:
                classifications.append("Odd Positive")
        return classifications

def solution(numbers: List[int]) -> List[str]:
    """Wrapper function to use the NumberClassifier."""
    return NumberClassifier.classify_numbers(numbers)

