def solution(m, n):
    # Validate inputs
    if m <= 0 or n <= 0:
        raise ValueError("Grid dimensions must be positive integers.")
    if m > 100 or n > 100:
        raise ValueError("Grid dimensions must not exceed 100.")

    # Create a 2D DP table initialized to 1 for the first row and column
    dp = [[1 for _ in range(n)] for _ in range(m)]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

