def classify_numbers(numbers: List[int]) -> List[str]:
    """
    Classifies each number in the input list based on specific rules and returns the classification
    concatenated with the number itself.

    Args:
        numbers: A list of integers to be classified.

    Returns:
        A list of strings where each string is the classification of the corresponding number.
    """
    classifications = []
    for num in numbers:
        if num == 0:
            classification = "zero"
        elif num > 0:
            if num % 2 == 0:
                classification = "even"
            else:
                classification = "positive"
        else:  # num < 0
            if num % 2 == 0:
                classification = "even"
            else:
                classification = "negative"
        classifications.append(f"{classification} {num}")
    return classifications

