def solution(n):
    """
    This function generates a list of strings from 1 to n, replacing numbers with "Fizz" if divisible by 3,
    "Buzz" if divisible by 5, and "FizzBuzz" if divisible by both 3 and 5.

    Args:
    n (int): The upper limit of the range (inclusive), 1 <= n <= 100.

    Returns:
    list: A list of strings representing the transformed numbers from 1 to n.
    """
    result = []
    for num in range(1, n + 1):
        if num % 3 == 0 and num % 5 == 0:
            result.append("FizzBuzz")
        elif num % 3 == 0:
            result.append("Fizz")
        elif num % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(num))
    return result

