def solution(score):
    """
    Calculate the letter grade and pass/fail status based on the given score.

    Args:
        score (int): The student's score (0-100)

    Returns:
        str: Formatted string with grade and status
    """
    if score >= 90:
        grade = "A"
    elif score >= 80:
        grade = "B"
    elif score >= 70:
        grade = "C"
    elif score >= 60:
        grade = "D"
    else:
        grade = "F"

    status = "Passed" if grade in ["A", "B", "C"] else "Failed"

    return f"Grade: {grade} - Status: {status}"

